import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1177, own='cte_100.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 757 Emergency Medical Technician (EMT) Basic ----
H("757.d.1.A",3,"A rural county has volunteer crews, a private ambulance service and a hospital-based transport unit. A student describing these is explaining:","the EMS systems available to patients",["school bus routes","fire hydrant spacing","police patrol zones"],"EMS systems include public, private, volunteer and hospital-based services.")
H("757.d.1.A",4,"An EMS system is best described as a network that:","provides emergency medical care and transport for patients",["only repairs ambulances","only teaches CPR classes","only dispatches police"],"EMS is a coordinated care system.")
H("757.d.1.B",3,"A paramedic starts an IV and gives cardiac drugs, while the EMT-Basic assists with oxygen and splinting. This illustrates differences in:","scope of practice among EMS provider levels",["uniform colors","shift lengths","ambulance brands"],"Scope of practice defines what each level may do.")
H("757.d.1.B",4,"An EMT-Basic should perform only skills that are:","within their scope of practice and local protocols",["requested by bystanders","learned from videos","performed by paramedics anywhere"],"Scope is set by law and medical direction.")
H("757.d.1.C",3,"Before a shift, an EMT-Basic checks that gloves, eye protection and a clean uniform are ready and gets enough sleep. This reflects responsibilities related to:","personal safety, health and professional readiness",["billing rules","vehicle paint","radio brands"],"EMTs protect themselves to protect patients.")
H("757.d.1.C",4,"Which habit supports an EMT-Basic's personal health and wellness?","maintaining physical fitness and current immunizations",["skipping vaccinations","working without breaks","ignoring injuries"],"Fitness and immunizations reduce risk.")
H("757.d.1.D",3,"A student reads the Texas rules that decide who may be certified and what an EMT may do. This summarizes:","state statutes and regulations governing EMS systems",["school dress codes","parking ordinances","sports bylaws"],"State law governs EMS licensing and practice.")
H("757.d.1.D",4,"In Texas, EMS personnel are certified and regulated primarily by the:","Department of State Health Services",["Texas Education Agency","Parks and Wildlife","Texas Lottery Commission"],"DSHS oversees EMS certification.")
H("757.d.1.E",3,"A town compares 911 calls, text-to-911 and direct station walk-ins as ways to reach help. This researches:","methods of accessing an EMS system",["methods of paying taxes","methods of voting","methods of filing reports"],"Access methods include 911 and enhanced 911.")
H("757.d.1.E",4,"Enhanced 911 helps dispatchers because it can:","show the caller's location automatically",["send flowers","block calls","charge callers"],"E911 displays location data.")
H("757.d.2.A",3,"A nursing home patient hands the crew a signed form saying not to attempt resuscitation. This is a:","do not resuscitate (DNR) directive",["billing receipt","vaccine record","menu order"],"A DNR directs no CPR in arrest.")
H("757.d.2.A",4,"An out-of-hospital DNR order is meant to:","state the patient's wishes about resuscitation outside a hospital",["order extra tests","transfer ownership of property","cancel insurance"],"It documents resuscitation wishes.")
H("757.d.2.B",3,"An unconscious man is bleeding badly and no relative is present, so the crew treats him. A conscious woman says 'yes, please help me.' These show:","implied consent and expressed consent",["no consent and refusal","forced consent and bribes","only written consent"],"Implied consent covers unresponsive patients; expressed is stated.")
H("757.d.2.B",4,"Consent a patient gives by speaking or nodding is called:","expressed consent",["implied consent","forced consent","assumed refusal"],"Expressed = actively given.")
H("757.d.2.C",3,"An EMT introduces themself, explains what will be done in simple words and asks permission before touching the patient. This models:","appropriate methods for obtaining consent",["avoiding the patient","skipping explanation","reading a manual aloud"],"Explain, then ask.")
H("757.d.2.C",4,"Before treating a conscious adult, the EMT should first:","explain the care and ask permission",["restrain them","call a lawyer","begin without speaking"],"Informed consent starts with explanation.")
H("757.d.2.D",3,"An ambulance is dispatched, arrives and begins care on a patient who needs help. This is part of conditions that create:","a legal duty to act",["a vacation","a refund","an exemption"],"Duty arises when the crew is dispatched and responds.")
H("757.d.2.D",4,"An EMT-Basic on duty has a duty to act once:","dispatched and in contact with a patient needing care",["a bystander gives an order","a friend asks for a favor","the shift ends"],"Duty begins at dispatch and patient contact.")
H("757.d.2.E",3,"A crew keeps a patient's diagnosis private except to the receiving hospital. This shows the importance of:","patient confidentiality and its legal protections",["gossip","advertising","social media posting"],"Privacy laws like HIPAA protect patient data.")
H("757.d.2.E",4,"A law that protects the privacy of patient health information is:","HIPAA",["FERPA","OSHA","ADA"],"HIPAA covers health privacy.")
H("757.d.2.F",3,"At a possible assault scene, a crew treats the victim but avoids touching unrelated items and writes down what they moved. This is how to:","preserve a crime scene",["clean a crime scene","destroy evidence","ignore a scene"],"Limit disturbance and document changes.")
H("757.d.2.F",4,"At a crime scene, an EMT-Basic should avoid:","moving or touching items not needed for patient care",["noting what was changed","staying aware of hazards","calling for police"],"Protect evidence.")
H("757.d.2.G",3,"A crew arrives to a stabbing and a child showing signs of abuse. These situations require the EMT-Basic to:","notify local law enforcement",["wait a week","hide the report","post online"],"Violence and abuse are reportable.")
H("757.d.2.G",4,"Which situation requires an EMT to notify law enforcement?","suspected child abuse",["a sprained ankle at a ballgame","a mild headache","a missed meal"],"Abuse is mandatory to report.")
H("757.d.3.A",3,"A report says a wound is lateral to the knee and an injury is distal to the elbow. These are:","anatomical terms of direction",["cooking terms","music terms","sports terms"],"Direction terms describe location.")
H("757.d.3.A",4,"The term proximal describes a location that is:","closer to the point of attachment or trunk",["farther from the trunk","on the back","toward the side"],"Proximal means nearer the trunk.")
H("757.d.3.B",3,"A student maps how air enters the lungs, how the heart pumps blood and how the brain controls movement. This describes basic:","anatomy and physiology of major body systems",["car repair","art history","tax law"],"A&P underpins patient care.")
H("757.d.3.B",4,"The primary job of the respiratory system is to:","move oxygen in and carbon dioxide out of the blood",["digest food","make bone","filter urine"],"Gas exchange occurs in the lungs.")
H("757.d.4.A",3,"A patient breathes 16 times a minute with equal chest rise and pink skin; another gasps with blue lips. These compare signs of:","adequate and inadequate breathing",["hunger and thirst","strength and speed","hearing and sight"],"Skin color and rate show adequacy.")
H("757.d.4.A",4,"Which is a sign of inadequate breathing?","cyanosis with labored effort",["pink skin","regular chest rise","normal speech"],"Blue discoloration is inadequate.")
H("757.d.4.B",3,"A suction unit is placed within arm's reach before opening the airway of a vomiting patient. This shows why:","suction must be ready for immediate use",["suction is optional","suction is decorative","suction wastes time"],"Fluids can block the airway quickly.")
H("757.d.4.B",4,"Having suction ready is important because airway fluids can:","quickly obstruct breathing",["improve oxygen","cool the patient","relieve pain"],"Blood and vomit block airways.")
H("757.d.4.C",3,"A trainee measures the catheter, inserts it without suction, then applies suction while withdrawing. This demonstrates:","proper suctioning technique to clear the airway",["wasteful practice","pushing fluid deeper","skipping a step"],"Suction only on withdrawal.")
H("757.d.4.C",4,"Suctioning an adult's mouth should generally be limited to about:","10 to 15 seconds at a time",["2 minutes","5 minutes","nonstop"],"Prolonged suction causes hypoxia.")
H("757.d.4.D",3,"A trainee measures from the corner of the mouth to the earlobe to size an airway tool. This demonstrates:","techniques and devices used to secure the airway",["splinting a leg","taking a pulse","logging a call"],"Sizing an oral airway uses that landmark.")
H("757.d.4.D",4,"An oropharyngeal airway is sized by measuring from the corner of the mouth to the:","angle of the jaw or earlobe",["knee","shoulder","belly button"],"That distance fits the OPA.")
H("757.d.4.E",3,"A crew performs a head-tilt chin-lift, then a jaw-thrust when a spine injury is possible. These are:","basic airway techniques",["advanced surgery","imaging methods","billing steps"],"Basic airway maneuvers open the airway.")
H("757.d.4.E",4,"The jaw-thrust maneuver is used instead of head-tilt when:","a spinal injury is suspected",["the patient is awake and hungry","the patient is a pet","the airway is already clear"],"It avoids neck movement.")
H("757.d.4.F",3,"A crew attaches a small sensor to the breathing circuit that displays exhaled carbon dioxide. This is the use of:","end-tidal capnography (ETCO2)",["a thermometer","a scale","a stethoscope"],"ETCO2 monitors ventilation.")
H("757.d.4.F",4,"End-tidal capnography measures:","carbon dioxide in exhaled breath",["blood sugar","body weight","hearing level"],"ETCO2 reflects ventilation.")
H("757.d.4.G",3,"A monitor shows a normal rectangular waveform with a reading near 35–45 mmHg. This suggests:","adequate ventilation",["no ventilation at all","a broken screen","a dead monitor"],"Normal ETCO2 is about 35–45.")
H("757.d.4.G",4,"A flat ETCO2 waveform with a reading of zero after intubation may indicate:","the tube is not in the airway or there is no breathing",["perfect ventilation","a happy patient","the monitor is too warm"],"No CO2 means no exhaled air.")
H("757.d.4.H",3,"A trained EMT inserts an advanced device above the vocal cords to maintain an airway when bag-valve-mask ventilation is inadequate. This is a:","supraglottic airway device",["feeding tube","splint","blood pressure cuff"],"Supraglottic devices sit above the glottis.")
H("757.d.4.H",4,"An example of a supraglottic airway device is the:","i-gel",["tourniquet","cervical collar","glucometer"],"i-gel is a supraglottic airway.")
H("757.d.5.A",3,"On arrival at a highway collision, the crew first looks for traffic, fuel leaks and downed wires. This is evaluating:","scene hazards to responders, patients and bystanders",["the weather forecast only","the radio signal","the ambulance's paint"],"Scene size-up begins with safety.")
H("757.d.5.A",4,"The first priority on arrival at an emergency scene is:","scene safety",["paperwork","billing","photography"],"Never become a second victim.")
H("757.d.5.B",3,"A crew counts the patients, notes the mechanism of injury and decides to request more units. This is:","scene assessment and resource determination",["a lunch break","a training exam","a shift change"],"Size-up decides resources.")
H("757.d.5.B",4,"After noting more patients than the crew can manage, the EMT should:","request additional resources",["leave the scene","treat only one","wait silently"],"Call for help early.")
H("757.d.5.C",3,"The EMT forms a general impression and checks responsiveness, airway, breathing and circulation first. This is the:","initial patient assessment",["billing audit","equipment inventory","vehicle inspection"],"Initial assessment finds life threats.")
H("757.d.5.C",4,"During an initial assessment, life-threatening problems are found by checking:","airway, breathing and circulation",["hair color","shoe size","birth month"],"ABCs guide priority.")
H("757.d.5.D",3,"At a bus crash with ten victims, the crew tags each patient red, yellow, green or black. This demonstrates:","a triage method to determine patient priority",["a filing system","a pay scale","a shift roster"],"Triage assigns priority.")
H("757.d.5.D",4,"In color-coded triage, red usually means the patient:","needs immediate treatment",["can wait","is deceased","walks away"],"Red = immediate.")
H("757.d.5.E",3,"A crew checks a fall victim's head, neck, chest, abdomen, pelvis and limbs for deformities, tenderness and swelling. This is assessing:","traumatic injuries",["hunger","sleepiness","boredom"],"Rapid trauma assessment looks for DCAP-BTLS signs.")
H("757.d.5.E",4,"DCAP-BTLS is a memory aid for finding signs of:","trauma during a physical assessment",["weather","traffic","billing"],"Deformities, contusions, abrasions, punctures, burns, tenderness, lacerations, swelling.")
H("757.d.5.F",3,"The EMT asks questions about symptoms, allergies and medications, then takes vital signs. This is the components of:","a focused patient assessment and history",["a repair order","a menu review","a vehicle test"],"SAMPLE and OPQRST organize the history.")
H("757.d.5.F",4,"The SAMPLE history includes questions about:","signs/symptoms, allergies, medications and past history",["vacation, cars and weather","music, sports and fashion","money, jobs and phones"],"SAMPLE structures history taking.")
H("757.d.5.G",3,"On a stable patient en route, the EMT performs a head-to-toe check without rushing. This is a:","detailed physical examination",["quick glance","phone call","paperwork"],"Detailed exam is thorough, when time permits.")
H("757.d.5.G",4,"A detailed physical exam is generally performed:","after life threats are managed and time allows",["before checking responsiveness","on every patient first","never"],"It follows the primary survey.")
H("757.d.5.H",3,"A dispatcher relays a call to the unit by radio, and the crew reports to the hospital by cell phone. These are components of:","common EMS communication systems",["a billing system","a menu system","an alarm clock"],"Radio and phone are core tools.")
H("757.d.5.H",4,"When reporting to the hospital by radio, the EMT should:","speak clearly and give a concise, organized report",["speak quickly and mumble","share unrelated details","use slang"],"Clear reports aid hospital prep.")
H("757.d.5.I",3,"After transport, an EMT records times, vital signs, treatments and patient condition on a form. This is a:","pre-hospital patient care report",["recipe card","time card for school","grocery list"],"The PCR documents care.")
H("757.d.5.I",4,"A written patient care report should be:","accurate, complete and objective",["short and vague","opinionated","left blank"],"Documentation must be factual.")
H("757.d.5.J",3,"A patient is assessed and declines transport; the EMT documents the findings, risks explained and signatures. This describes:","a no-transport report",["a billing dispute","an insurance claim","a maintenance form"],"Document refusal thoroughly.")
H("757.d.5.J",4,"A no-transport report should include:","assessment findings and the patient's refusal documentation",["only the ambulance number","only the weather","the driver's lunch"],"It records what happened and why.")
H("757.d.5.K",3,"A competent adult declines care after the EMT explains the risks. This analysis involves legal considerations of:","patient refusal",["a free ride","vehicle licensing","parking permits"],"Competent patients may refuse.")
H("757.d.5.K",4,"For a patient to legally refuse care, they must be:","competent and informed of the risks",["intoxicated","unconscious","a minor alone"],"Capacity and information are required.")
H("757.d.6.A",3,"A patient shows chest pressure, wheezing, sudden weakness on one side or sweaty confusion. These are:","signs and symptoms of medical emergencies",["signs of fitness","signs of luck","signs of rest"],"Recognize emergency presentations.")
H("757.d.6.A",4,"Sudden weakness on one side of the body with slurred speech suggests:","a stroke",["a sprain","a cold","a rash"],"Face droop, arm weakness, speech difficulty.")
H("757.d.6.B",3,"For each medical emergency, a protocol says to give oxygen, position the patient and monitor vitals. This describes:","medical care for medical emergencies",["billing steps","repair steps","filing steps"],"Care follows protocol.")
H("757.d.6.B",4,"A patient in respiratory distress is commonly positioned:","sitting up in a position of comfort",["flat on their stomach","head below the heart","standing"],"Upright eases breathing.")
H("757.d.6.C",3,"An EMT-Basic may help a patient take their own prescribed nitroglycerin or give oxygen, glucose or aspirin per protocol. These are:","common medications EMT-Basics may administer",["surgical drugs","chemotherapy drugs","anesthetics"],"EMT-Basic meds are limited.")
H("757.d.6.C",4,"A medication an EMT-Basic may give for suspected heart attack is:","aspirin",["morphine","insulin","antibiotics"],"Aspirin is commonly allowed.")
H("757.d.6.D",3,"A person with asthma, COPD or pneumonia struggles to breathe and wheezes. These are:","common respiratory emergencies",["bone injuries","burn injuries","eye injuries"],"They disrupt airflow or gas exchange.")
H("757.d.6.D",4,"Wheezing is typically a sign of:","narrowed airways",["a broken arm","low blood sugar","a rash"],"Airway narrowing causes wheezes.")
H("757.d.6.E",3,"The EMT sits the patient up, administers oxygen and assists with a prescribed inhaler. This is appropriate care for:","respiratory distress",["a sprain","a burn","a nosebleed"],"Oxygen and bronchodilators help.")
H("757.d.6.E",4,"An EMT may assist with a patient's prescribed inhaler if the patient:","has a prescription and medical direction allows it",["wants one","is unconscious","is a child alone"],"Requires authorization.")
H("757.d.6.F",3,"A man with crushing chest pain radiating to the arm, and a woman with face droop, are examples of:","cardiovascular emergencies",["skin conditions","vision issues","sleep problems"],"Heart attack and stroke are cardiovascular emergencies.")
H("757.d.6.F",4,"Chest pain with sweating and nausea may indicate:","a heart attack",["a sprain","a sunburn","a cold"],"Classic acute coronary signs.")
H("757.d.6.G",3,"A trainee places electrodes on both wrists, both ankles and six chest positions. This demonstrates standard placement for a:","12-lead ECG",["thermometer","splint","scale"],"Limb and chest leads form 12 leads.")
H("757.d.6.G",4,"Proper electrode placement is important because it:","produces an accurate heart tracing",["adds weight","cools the patient","hides symptoms"],"Misplacement distorts the ECG.")
H("757.d.6.H",3,"Crews send an ECG to the emergency department from the field so the hospital can prepare. This explains the purpose of:","transmitting a 12-lead ECG",["billing codes","dispatch logs","parking tickets"],"Early notification speeds care.")
H("757.d.6.H",4,"Transmitting a 12-lead ECG from the scene helps the hospital to:","prepare for a possible heart attack before arrival",["close the unit","delay the patient","avoid treatment"],"Pre-arrival activation saves time.")
H("757.d.6.I",3,"In a simulation, a trainee assists a patient with prescribed nitroglycerin for chest pain after checking blood pressure. This simulates:","administration of prescribed nitroglycerin",["feeding the patient","giving antibiotics","cleaning a wound"],"Nitroglycerin relaxes vessels.")
H("757.d.6.I",4,"Before assisting with nitroglycerin, the EMT must confirm the patient's:","blood pressure is adequate and the drug is prescribed to them",["favorite color","insurance card","address"],"Hypotension is a contraindication.")
H("757.d.6.J",3,"A crew attaches pads to an unresponsive pulseless patient and follows prompts. This demonstrates the use of an:","automated external defibrillator",["oxygen tank","suction unit","splint"],"AED analyzes rhythm and shocks.")
H("757.d.6.J",4,"An AED should be used on a patient who is:","unresponsive, not breathing and without a pulse",["alert and talking","walking","sleeping normally"],"AEDs treat cardiac arrest.")
H("757.d.6.K",3,"A confused diabetic patient is sweaty, shaky and irritable. This identifies signs of altered mental status associated with:","low or high blood sugar",["broken bones","burns","hearing loss"],"Diabetic emergencies alter mentation.")
H("757.d.6.K",4,"Altered mental status in a diabetic patient may be caused by:","hypoglycemia",["new shoes","a haircut","a vacation"],"Low sugar causes confusion.")
H("757.d.6.L",3,"A conscious diabetic patient with low sugar is given oral glucose after the EMT confirms they can swallow. This lists steps for care of:","a hypoglycemic patient",["a burn patient","a fracture patient","a choking patient"],"Give sugar if able to swallow.")
H("757.d.6.L",4,"Oral glucose should be given to a hypoglycemic patient only if they are:","awake and able to swallow",["unconscious","vomiting heavily","unable to follow commands"],"Aspiration risk otherwise.")
H("757.d.6.M",3,"After a bee sting, a patient develops hives, swelling of the face and difficulty breathing. These are signs of:","an allergic reaction",["a cold","a sprain","a fever"],"Anaphylaxis involves multiple systems.")
H("757.d.6.M",4,"A severe allergic reaction may cause:","airway swelling and low blood pressure",["lower pulse always","better breathing","a rash only"],"Anaphylaxis threatens airway and circulation.")
H("757.d.6.N",3,"The EMT supports the airway, gives oxygen and helps with the patient's prescribed epinephrine auto-injector. This is care for:","allergic reactions including anaphylaxis",["a minor scrape","a bruise","a headache"],"Epinephrine reverses anaphylaxis.")
H("757.d.6.N",4,"An epinephrine auto-injector is used to treat:","severe allergic reactions",["broken bones","burns","seizures"],"It reverses anaphylaxis.")
H("757.d.6.O",3,"A toddler is found near an open cabinet of cleaners with burns around the mouth. These are signs of:","poisoning",["a sprain","a cold","a fever"],"Look for source and signs.")
H("757.d.6.O",4,"Poison can enter the body through:","ingestion, inhalation, absorption and injection",["only touch with sight","only hearing","only bright lights"],"Four routes of entry.")
H("757.d.6.P",3,"The EMT contacts Poison Control, identifies the substance and follows direction before giving any treatment. This is care for:","suspected poisoning",["a sprain","a burn","a fracture"],"Poison Control guides treatment.")
H("757.d.6.P",4,"The national Poison Help line number is:","1-800-222-1222",["1-800-555-0000","1-900-123-4567","1-888-999-1111"],"Poison Help is 1-800-222-1222.")
H("757.d.6.Q",3,"The EMT counts a pulse, counts respirations, measures blood pressure and notes skin color and temperature. These are:","vital signs",["billing codes","dispatch notes","vehicle checks"],"Vitals trend patient condition.")
H("757.d.6.Q",4,"A normal resting adult pulse is about:","60 to 100 beats per minute",["10 to 20","150 to 200","300"],"Typical adult pulse.")
H("757.d.6.R",3,"Two EMTs use proper body mechanics to lift a stretcher while keeping their backs straight and legs bent. This is:","proper techniques for lifting and moving patients",["unsafe lifting","random lifting","speed lifting"],"Protect the back; use legs.")
H("757.d.6.R",4,"When lifting, an EMT should keep the load:","close to the body with the back straight",["far from the body","twisted","overhead"],"Reduce strain.")
H("757.d.6.S",3,"A swimmer pulled from a pool is coughing, short of breath and pale. This lists signs of:","a water-related emergency such as near-drowning",["a sunburn","a headache","a cold"],"Drowning can cause respiratory distress.")
H("757.d.6.S",4,"The priority for a near-drowning patient is:","airway and breathing",["a tan","a snack","paperwork"],"Ventilation is first.")
H("757.d.6.T",3,"A patient who is severely agitated, paranoid and threatening to harm themselves presents a:","behavioral emergency",["sprain","burn","bruise"],"Behavior is a medical concern.")
H("757.d.6.T",4,"A behavioral emergency can affect patient care by:","making the scene less safe and limiting cooperation",["improving cooperation","making care easier","removing hazards"],"Behavior can increase risk.")
H("757.d.6.U",3,"Before transporting a patient with a psychiatric crisis, the EMT considers consent, capacity and whether law enforcement is needed. This identifies:","medical and legal considerations in psychological emergencies",["menu choices","tax rules","vehicle colors"],"Capacity and safety matter.")
H("757.d.6.U",4,"In a psychological emergency, an EMT should be aware of:","the patient's rights and legal requirements for treatment",["only the weather","only paperwork length","only radio brands"],"Legal rights apply.")
H("757.d.6.V",3,"The EMT stays calm, speaks gently, keeps a safe distance and listens. This describes emergency care for a patient with:","a behavioral problem",["a laceration","a fracture","a burn"],"De-escalation supports safety.")
H("757.d.6.V",4,"A helpful approach with an agitated patient is to:","stay calm, listen and avoid sudden movements",["argue","shout","crowd them"],"De-escalate.")
H("757.d.6.W",3,"If a combative patient may injure themselves or others, trained crews use approved restraint with enough personnel and documentation. This describes:","safe restraint techniques",["any force","random methods","no plan"],"Restraint must be safe and justified.")
H("757.d.6.W",4,"When restraint is used, the EMT must make sure the patient's:","airway and breathing are not compromised",["hands are hidden","voice is silent","face is covered"],"Never restrict breathing.")
H("757.d.6.X",3,"A pregnant patient reports severe abdominal pain and vaginal bleeding. These are signs that can indicate:","a medical problem during pregnancy",["a normal day","a minor cold","a haircut"],"Bleeding and pain are warning signs.")
H("757.d.6.X",4,"Which is a warning sign in a pregnant patient?","vaginal bleeding with severe pain",["mild fatigue","slight appetite change","normal movement"],"Bleeding with pain needs urgent care.")
H("757.d.6.Y",3,"The EMT places a pregnant patient on her left side, gives oxygen and transports promptly. This identifies procedures to:","stabilize a pregnant patient showing warning signs",["ignore her","delay transport","remove oxygen"],"Left-side positioning improves circulation.")
H("757.d.6.Y",4,"Positioning a pregnant patient on her left side helps because it:","keeps the uterus from pressing on major blood vessels",["slows breathing","raises blood sugar","warms the body"],"Avoids vena cava compression.")
H("757.d.7.A",3,"A patient with a severe injury has pale, cool skin, a weak fast pulse and falling blood pressure. This describes how shock affects:","the cardiovascular and other major body systems",["only the hair","only the nails","only the teeth"],"Shock reduces perfusion across systems.")
H("757.d.7.A",4,"In shock, the body's cells are harmed because they do not receive enough:","oxygen-rich blood",["sunlight","noise","exercise"],"Hypoperfusion starves tissue.")
H("757.d.7.B",3,"A crew applies direct pressure, then a pressure dressing, and uses a tourniquet if bleeding continues on a limb. This is care for:","controlling external bleeding",["a rash","a cough","a headache"],"Escalate from pressure to tourniquet.")
H("757.d.7.B",4,"The first step to control most external bleeding is:","direct pressure with a dressing",["a hot pack","a drink of water","walking it off"],"Direct pressure first.")
H("757.d.7.C",3,"A patient has a rigid, tender abdomen, dizziness and rapid pulse after a fall with no visible wound. These are signs of:","internal bleeding",["indigestion only","a sunburn","a cold"],"Internal bleeding may be hidden.")
H("757.d.7.C",4,"Which finding suggests internal bleeding?","a tender, distended abdomen with signs of shock",["a clean scrape","a mild itch","a hiccup"],"Distension and shock signs.")
H("757.d.7.D",3,"After a steering-wheel impact, the EMT suspects bleeding in the chest and abdomen from the crash forces. This identifies internal bleeding by:","mechanism of injury",["birth date","favorite team","shoe size"],"MOI predicts injuries.")
H("757.d.7.D",4,"A high-speed collision with a bent steering wheel should make the EMT suspect:","serious internal injuries",["no injury at all","only a bruise","a minor issue"],"Significant MOI warrants concern.")
H("757.d.7.E",3,"A cut, a bruise and a crushing injury with swelling represent open, closed and blunt types of:","soft tissue injuries",["bone diseases","lung diseases","eye diseases"],"Soft tissue injuries vary.")
H("757.d.7.E",4,"A wound in which the skin is broken is called:","an open wound",["a closed wound","a contusion","a bruise"],"Open wounds break the skin.")
H("757.d.7.F",3,"The EMT applies a cold pack, rests and elevates a swollen bruised limb. This is care for a:","closed soft tissue injury such as a contusion",["burn","laceration","amputation"],"RICE-type care limits swelling.")
H("757.d.7.F",4,"For a closed soft tissue injury, applying cold helps to:","reduce swelling and pain",["increase bleeding","raise temperature","stop breathing"],"Cold limits swelling.")
H("757.d.7.G",3,"A trainee covers a laceration with sterile gauze, then wraps a bandage snugly while checking circulation below it. This demonstrates:","dressing wounds and applying bandages",["tying a shoe","cooking","gardening"],"Dress then bandage; check pulses.")
H("757.d.7.G",4,"After applying a bandage to a limb, the EMT should check:","circulation, sensation and movement below it",["the weather","the driver's shift","the radio"],"Avoid bandages that are too tight.")
H("757.d.7.H",3,"A student labels the femur, humerus and skull and explains how bones support and protect the body. This identifies:","bones and functions of the musculoskeletal system",["organs of digestion","nerves of the eye","glands"],"Bones support, protect and move.")
H("757.d.7.H",4,"The primary function of the skull is to:","protect the brain",["pump blood","digest food","filter air"],"Skull encloses the brain.")
H("757.d.7.I",3,"One patient has a broken bone piercing the skin; another has a broken bone with intact skin. This identifies:","open and closed fractures",["strains and sprains","burns and frostbite","cuts and scrapes"],"Open fractures break the skin.")
H("757.d.7.I",4,"In an open fracture, the major added risk compared with a closed fracture is:","infection and bleeding",["better healing","less pain always","no treatment needed"],"Skin break exposes bone.")
H("757.d.7.J",3,"The EMT pads a swollen, deformed forearm and splints it above and below the injury. This demonstrates:","immobilization of a painful, swollen, deformed extremity",["rubbing the arm","stretching the arm","ignoring the arm"],"Splint the joints above and below.")
H("757.d.7.J",4,"Before and after splinting a limb, the EMT should check:","pulse, sensation and movement distal to the injury",["the patient's hair","the ambulance tires","the weather report"],"PMS checks protect circulation.")
H("757.d.7.K",3,"A student explains how the spinal cord carries signals from the brain through the bony vertebrae that surround it. This analyzes the relationship between the:","skeletal and nervous systems",["muscular and digestive systems","respiratory and urinary systems","lymph and skin systems"],"Vertebrae protect the cord.")
H("757.d.7.K",4,"Damage to the spine is serious mainly because it can injure the:","spinal cord",["fingernails","hair","teeth"],"Cord injury can cause paralysis.")
H("757.d.7.L",3,"A diving into a shallow pool and a high-speed rollover are examples of mechanisms that can cause:","cervical spine injury",["a sunburn","a cold","a toothache"],"Axial load and flexion injure the neck.")
H("757.d.7.L",4,"A mechanism that suggests possible neck injury is:","a fall from a height",["a paper cut","a sneeze","a nap"],"Falls can injure the cervical spine.")
H("757.d.7.M",3,"The EMT holds the head in line, applies a properly sized collar and secures the patient to a board. This applies:","stabilization techniques for cervical spine injuries",["lifting the head","bending the neck","shaking the patient"],"Manual stabilization and collar.")
H("757.d.7.M",4,"Manual in-line stabilization of the head is used to:","prevent movement of a possibly injured neck",["wake the patient","drain fluids","warm the head"],"Keep the spine aligned.")
H("757.d.8.A",3,"A toddler has a faster breathing rate and smaller airway than an adult, so the crew adjusts equipment size. This differentiates care for:","infants, children and adults",["students only","animals","machines"],"Pediatric anatomy differs.")
H("757.d.8.A",4,"Compared with adults, an infant's airway is:","smaller and easier to block",["larger","identical","immune to blockage"],"Infants obstruct more easily.")
H("757.d.8.B",3,"A choking baby is placed face-down on the rescuer's forearm and given back blows and chest thrusts. This demonstrates techniques for:","foreign body airway obstruction in an infant",["feeding","burping","bathing"],"Infant FBAO uses back blows and chest thrusts.")
H("757.d.8.B",4,"For a conscious choking adult, the rescuer should give:","abdominal thrusts",["a hug","a glass of water","a back rub"],"Heimlich maneuver.")
H("757.d.8.C",3,"A crew assesses a child, uses a bag-valve-mask with a child-size mask and gives oxygen. This demonstrates:","pediatric assessment and ventilation support",["adult-only care","ignoring the child","skipping oxygen"],"BVM sizing matters.")
H("757.d.8.C",4,"When using a bag-valve-mask on a child, the mask must:","fit snugly over the nose and mouth",["be as large as possible","be upside down","be loose"],"A seal is needed.")
H("757.d.8.D",3,"The EMT protects a seizing child from injury, gives oxygen and treats a respiratory emergency. This describes care for:","pediatric emergencies such as seizures and respiratory distress",["a paper cut","a stubbed toe","a cold sore"],"Protect and support breathing.")
H("757.d.8.D",4,"During a seizure, the EMT should:","protect the patient from injury and not restrain them",["hold them down","put something in their mouth","shake them"],"Do not restrain.")
H("757.d.9.A",3,"A state law says when an ambulance may exceed the speed limit and what it must do at red lights. This describes:","state laws related to the operation of an ambulance",["school bus rules","pedestrian rules","bicycle rules"],"State statutes govern emergency vehicles.")
H("757.d.9.A",4,"When operating an ambulance with lights and siren, the driver must still:","drive with due regard for the safety of others",["ignore all traffic","drive recklessly","avoid training"],"Due regard applies.")
H("757.d.9.B",3,"A trainee sorts terms: removing dirt, killing most germs, killing nearly all germs and killing all microbes. These define:","cleaning, disinfection, high-level disinfection and sterilization",["cooking steps","painting steps","packing steps"],"Levels of decontamination differ.")
H("757.d.9.B",4,"Sterilization is the process that:","destroys all microbial life",["removes visible dirt only","lowers temperature","adds soap"],"Highest level of germ kill.")
H("757.d.9.C",3,"After a call, crews wipe the stretcher with an approved disinfectant and replace used linens. This describes how to:","clean and disinfect patient care equipment",["ignore equipment","reuse sheets","skip cleaning"],"Cleaning protects patients.")
H("757.d.9.C",4,"After transporting a patient, a stretcher should be:","cleaned and disinfected before the next patient",["left dirty","painted","taken apart"],"Prevent cross-contamination.")
H("757.d.9.D",3,"For a bleeding trauma patient, the EMT wears gloves, eye protection and a gown. This identifies types and uses of:","personal protective equipment",["dress clothes","game gear","sports equipment"],"PPE protects the responder.")
H("757.d.9.D",4,"Standard precautions require which minimum PPE when contact with body fluids is possible?","gloves",["a sun hat","sandals","earrings"],"Gloves are the baseline.")
H("757.d.9.E",3,"At a crash, a rescue team uses tools to free a trapped driver without causing more injury. This explains the purpose of:","patient extrication",["parking","towing for fees","car washing"],"Extrication removes patients safely.")
H("757.d.9.E",4,"A key principle of extrication is to:","protect the patient from further injury",["work as quickly as possible regardless","avoid communication","skip planning"],"Patient safety first.")
H("757.d.9.F",3,"A rescuer opens an unlocked door; another must cut the roof with tools. This distinguishes:","simple and complex access methods",["fast and slow breathing","hot and cold","dry and wet"],"Simple = no tools; complex = tools.")
H("757.d.9.F",4,"An example of simple access to a vehicle is:","opening an unlocked door",["cutting the roof","using hydraulic spreaders","breaking all windows"],"Simple access uses no tools.")
H("757.d.9.G",3,"At a spill with unknown liquid, the EMT stays outside the hot zone and waits for hazmat teams. This describes the EMT's role during:","a hazardous materials incident",["a ball game","a parade","a picnic"],"EMTs avoid contamination.")
H("757.d.9.G",4,"At a hazardous materials incident, an EMT-Basic should treat patients only after they are:","decontaminated and in a safe area",["still contaminated","in the hot zone","untouched"],"Decon before treatment.")
H("757.d.9.H",3,"On arrival at a scene where a crash involves many victims, the EMT notifies dispatch, sets up command and follows the plan in order. This describes the sequential steps in:","responding to a multiple-casualty incident",["a routine call","a vacation","a drill only"],"Command and communication first.")
H("757.d.9.H",4,"One of the first actions at a large incident is to:","establish command and request resources",["start billing","go home","disband units"],"Command structure is first.")
H("757.d.9.I",3,"A response involving more patients than the first crew can handle is classified as a:","multiple-casualty incident",["training day","minor call","service check"],"MCI exceeds routine resources.")
H("757.d.9.I",4,"A multiple-casualty incident is generally defined by:","the number of patients overwhelming available resources",["time of day","type of ambulance","weather"],"Resources vs. need.")
H("757.d.9.J",3,"A tornado hits a town and the county declares a disaster, activating plans and mutual aid. This describes criteria to:","initiate disaster operations",["end operations","avoid operations","ignore events"],"Large scale triggers disaster mode.")
H("757.d.9.J",4,"A disaster operation is typically triggered when an event:","overwhelms normal local EMS capacity",["is routine","is minor","is planned"],"Capacity exceeded.")
H("757.d.9.K",3,"At a mass casualty scene, the crew sorts patients quickly using START to assign priority. This demonstrates:","triage principles used during a mass casualty incident",["a billing method","a sorting game","an inventory count"],"Triage maximizes lives saved.")
H("757.d.9.K",4,"The goal of triage during a mass casualty incident is to:","do the greatest good for the greatest number",["treat the loudest first","treat friends first","treat nobody"],"Prioritize by urgency and survivability.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_100.jsonl"))
